import 'jsr:@supabase/functions-js/edge-runtime.d.ts';

import type { SupabaseClient } from 'jsr:@supabase/supabase-js@2';

import {
  BASIC_DETAILS,
  cachePlantInfo,
  corsHeaders,
  decodePlantImage,
  isPlantKingdom,
  json,
  NOT_A_GARDEN_PLANT_MESSAGE,
  parseCoordinates,
  plantIdFetch,
  requireUser,
  saveUserPlantWithPhoto,
  toBasicInfo,
  type PlantBasicInfoRow,
} from '../_shared/plants.ts';
import { generateFlowerPollenParams } from '../_shared/flower-pollen.ts';

function encodeBase64(bytes: Uint8Array): string {
  let binary = '';
  const chunkSize = 0x8000;
  for (let i = 0; i < bytes.length; i += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunkSize));
  }
  return btoa(binary);
}

async function rememberFlowerPollen(
  admin: SupabaseClient,
  plantId: string,
  image: string,
  scientificName: string | null,
  commonName: string | null
) {
  try {
    const { bytes, contentType } = await decodePlantImage(image);
    const constants = await generateFlowerPollenParams(
      encodeBase64(bytes),
      contentType,
      scientificName,
      commonName,
      null
    );
    if (!constants) {
      return;
    }
    const { error } = await admin
      .from('plants')
      .update({
        flower_ratio: constants.flower_ratio,
        pollen_per_flower_cm3: constants.pollen_per_flower_cm3,
      })
      .eq('id', plantId);
    if (error) {
      console.error(`rememberFlowerPollen: ${error.message}`);
    }
  } catch (error) {
    console.error('rememberFlowerPollen failed:', error);
  }
}

type IdentifyBody = {
  images?: string[];
  latitude?: number;
  longitude?: number;
  plant_id?: string;
  save?: boolean;
};

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  if (req.method !== 'POST') {
    return json({ error: 'Method not allowed' }, 405);
  }

  try {
    const { user, admin } = await requireUser(req);
    const body = (await req.json().catch(() => ({}))) as IdentifyBody;
    const images = Array.isArray(body.images)
      ? body.images.filter((image): image is string => typeof image === 'string' && image.length > 0)
      : [];

    if (images.length === 0) {
      return json({ error: 'Provide at least one image URL or base64 string' }, 400);
    }

    const coordinates = parseCoordinates(body);
    const shouldSave = body.save !== false;
    const taxonId = typeof body.plant_id === 'string' ? body.plant_id.trim() : '';

    // Confirm a photo preview: the taxon is already cached, so skip a second Plant.id call.
    if (shouldSave && taxonId) {
      const { data: cached, error: cachedError } = await admin
        .from('plant_basic_info')
        .select('*')
        .eq('plant_id', taxonId)
        .maybeSingle();

      if (cachedError) {
        return json({ error: `Failed to load plant details: ${cachedError.message}` }, 500);
      }
      if (!cached) {
        return json({ error: 'Plant details are not available to confirm' }, 400);
      }

      const cachedInfo = cached as PlantBasicInfoRow;
      if (!isPlantKingdom(cachedInfo.taxonomy)) {
        return json({ error: NOT_A_GARDEN_PLANT_MESSAGE }, 400);
      }

      const { updated_at: _updatedAt, ...info } = cachedInfo;
      const result = await saveUserPlantWithPhoto(admin, user.id, info, images[0]);
      await rememberFlowerPollen(
        admin,
        result.plant.id,
        images[0],
        info.scientific_name,
        info.common_names?.[0] ?? null
      );

      return json({
        added: true,
        plant: result.plant,
        info: result.info,
        photo: result.photo,
        location: coordinates,
      });
    }

    const identification = await plantIdFetch(`/identification?details=${BASIC_DETAILS}&language=en`, {
      method: 'POST',
      body: JSON.stringify({
        images,
        similar_images: true,
        suggestion_filter: { classification: 'vascular_plants OR bryophytes' },
        ...(coordinates ?? {}),
      }),
    });

    const isPlant = identification?.result?.is_plant;
    if (isPlant?.binary === false) {
      return json(
        {
          error: 'This photo does not appear to contain a plant',
          is_plant: isPlant,
        },
        400
      );
    }

    const suggestions = Array.isArray(identification?.result?.classification?.suggestions)
      ? identification.result.classification.suggestions
      : [];
    const top = suggestions.find((suggestion: { details?: Record<string, unknown> }) =>
      isPlantKingdom(
        suggestion?.details?.taxonomy && typeof suggestion.details.taxonomy === 'object'
          ? (suggestion.details.taxonomy as Record<string, unknown>)
          : null
      )
    );
    const plantId = typeof top?.id === 'string' ? top.id : null;
    const scientificName = typeof top?.name === 'string' ? top.name : null;

    if (!plantId || !top) {
      return json(
        {
          error: suggestions.length > 0 ? NOT_A_GARDEN_PLANT_MESSAGE : 'Plant.id did not return a species suggestion',
        },
        suggestions.length > 0 ? 400 : 502
      );
    }

    const info = toBasicInfo(plantId, scientificName, top.details ?? {});
    if (!isPlantKingdom(info.taxonomy)) {
      return json({ error: NOT_A_GARDEN_PLANT_MESSAGE }, 400);
    }
    const result = shouldSave
      ? await saveUserPlantWithPhoto(admin, user.id, info, images[0])
      : { plant: null, info: await cachePlantInfo(admin, info), photo: null };

    if (result.plant) {
      await rememberFlowerPollen(
        admin,
        result.plant.id,
        images[0],
        info.scientific_name,
        info.common_names?.[0] ?? null
      );
    }

    return json({
      added: shouldSave,
      plant: result.plant,
      info: result.info,
      photo: result.photo ?? null,
      location: coordinates,
      is_plant: isPlant ?? null,
      identification_access_token: identification?.access_token ?? null,
      similar_images: asSimilarImages(top.similar_images),
      suggestions: suggestions.map((suggestion: { id?: string; name?: string; probability?: number }) => ({
        id: suggestion.id ?? null,
        name: suggestion.name ?? null,
        probability: suggestion.probability ?? null,
      })),
    });
  } catch (error) {
    if (error instanceof Response) {
      return error;
    }

    const status = typeof (error as { status?: number }).status === 'number'
      ? (error as { status: number }).status
      : 500;
    return json(
      {
        error: error instanceof Error ? error.message : 'Photo identification failed',
        details: (error as { payload?: unknown }).payload ?? null,
      },
      status === 429 ? 429 : status
    );
  }
});

function asSimilarImages(value: unknown) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((item) => {
      if (!item || typeof item !== 'object') {
        return null;
      }

      const record = item as {
        url?: unknown;
        url_small?: unknown;
        citation?: unknown;
        license_name?: unknown;
        license_url?: unknown;
      };
      const url =
        typeof record.url === 'string' && record.url.length > 0
          ? record.url
          : typeof record.url_small === 'string' && record.url_small.length > 0
            ? record.url_small
            : null;

      if (!url) {
        return null;
      }

      return {
        url,
        citation: typeof record.citation === 'string' ? record.citation : null,
        license_name: typeof record.license_name === 'string' ? record.license_name : null,
        license_url: typeof record.license_url === 'string' ? record.license_url : null,
      };
    })
    .filter((image): image is NonNullable<typeof image> => image != null)
    .slice(0, 3);
}

import { createClient, type SupabaseClient, type User } from 'jsr:@supabase/supabase-js@2';

import type { GrowthMode } from './growth-curve.ts';
import { generateGrowthParams } from './growth-params-llm.ts';

export const PLANT_ID_BASE = 'https://plant.id/api/v3';

export const BASIC_DETAILS = [
  'common_names',
  'url',
  'taxonomy',
  'rank',
  'gbif_id',
  'inaturalist_id',
  'image',
  'edible_parts',
  'watering',
  'propagation_methods',
  'best_soil_type',
].join(',');

export const NOT_A_GARDEN_PLANT_MESSAGE =
  'Garden Grid only includes plants, not fungi or similar organisms.';

export function isPlantKingdom(taxonomy: Record<string, unknown> | null | undefined) {
  if (!taxonomy) {
    return true;
  }

  const kingdom = String(taxonomy.kingdom ?? '').trim().toLowerCase();
  return !kingdom || kingdom === 'plantae';
}

export const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

export type PlantBasicInfoRow = {
  plant_id: string;
  scientific_name: string | null;
  common_names: string[];
  taxonomy: Record<string, unknown> | null;
  rank: string | null;
  watering: { min?: number; max?: number } | null;
  propagation_methods: string[];
  edible_parts: string[];
  best_soil_type: string | null;
  image_url: string | null;
  url: string | null;
  gbif_id: number | null;
  inaturalist_id: number | null;
  updated_at: string;

  // Growth-curve params (see growth-curve.ts / growth-params-llm.ts).
  // Populated lazily by cachePlantInfo() via an LLM call, so all nullable.
  growth_mode: GrowthMode | null;
  l: number | null;
  k: number | null;
  x0: number | null;
  xg: number | null;
  kg: number | null;
  ks: number | null;
  xs: number | null;
  f: number | null;
  r: number | null;
  cycle_length: number | null;
  b_base: number | null;
  l_season: number | null;
  carbon_fraction: number | null;
  confidence: number | null;
  params_generated_at: string | null;
};

export function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
}

export type Coordinates = {
  latitude: number;
  longitude: number;
};

export function parseCoordinates(body: { latitude?: unknown; longitude?: unknown }): Coordinates | null {
  const latitude = typeof body.latitude === 'number' ? body.latitude : Number(body.latitude);
  const longitude = typeof body.longitude === 'number' ? body.longitude : Number(body.longitude);

  if (
    !Number.isFinite(latitude) ||
    !Number.isFinite(longitude) ||
    latitude < -90 ||
    latitude > 90 ||
    longitude < -180 ||
    longitude > 180
  ) {
    return null;
  }

  return { latitude, longitude };
}

export function plantIdKey() {
  const key = Deno.env.get('PLANTID_API_KEY');
  if (!key) {
    throw new Error('PLANTID_API_KEY is not set');
  }
  return key;
}

function asStringArray(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.filter((item): item is string => typeof item === 'string');
  }
  if (value && typeof value === 'object') {
    const fromEn = (value as { en?: unknown }).en;
    if (Array.isArray(fromEn)) {
      return fromEn.filter((item): item is string => typeof item === 'string');
    }
  }
  return [];
}

function asImageUrl(value: unknown): string | null {
  if (typeof value === 'string' && value.length > 0) {
    return value;
  }
  if (value && typeof value === 'object' && typeof (value as { value?: unknown }).value === 'string') {
    return (value as { value: string }).value;
  }
  return null;
}

function asText(value: unknown): string | null {
  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed.length > 0 ? trimmed : null;
  }
  if (Array.isArray(value)) {
    const parts = value
      .map((item) => (typeof item === 'string' ? item.trim() : ''))
      .filter((item) => item.length > 0);
    return parts.length > 0 ? parts.join(', ') : null;
  }
  if (value && typeof value === 'object') {
    const record = value as { value?: unknown; en?: unknown };
    return asText(record.value ?? record.en);
  }
  return null;
}

function asInt(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return value;
  }
  if (typeof value === 'string' && value.trim() !== '') {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

export function toBasicInfo(
  plantId: string,
  scientificName: string | null,
  details: Record<string, unknown> | null | undefined
): Omit<PlantBasicInfoRow, 'updated_at'> {
  const watering = details?.watering;
  return {
    plant_id: plantId,
    scientific_name: scientificName,
    common_names: asStringArray(details?.common_names),
    taxonomy: details?.taxonomy && typeof details.taxonomy === 'object'
      ? (details.taxonomy as Record<string, unknown>)
      : null,
    rank: typeof details?.rank === 'string' ? details.rank : null,
    watering:
      watering && typeof watering === 'object'
        ? (watering as { min?: number; max?: number })
        : null,
    propagation_methods: asStringArray(details?.propagation_methods),
    edible_parts: asStringArray(details?.edible_parts),
    best_soil_type: asText(details?.best_soil_type),
    image_url: asImageUrl(details?.image),
    url: typeof details?.url === 'string' ? details.url : null,
    gbif_id: asInt(details?.gbif_id),
    inaturalist_id: asInt(details?.inaturalist_id),
  };
}

export async function plantIdFetch(path: string, init?: RequestInit) {
  const response = await fetch(`${PLANT_ID_BASE}${path}`, {
    ...init,
    headers: {
      'Api-Key': plantIdKey(),
      'Content-Type': 'application/json',
      ...(init?.headers ?? {}),
    },
  });

  const payload = await response.json().catch(() => null);
  if (!response.ok) {
    const message =
      (payload && typeof payload === 'object' && 'error' in payload && payload.error) ||
      `Plant.id request failed (${response.status})`;
    const error = new Error(String(message));
    (error as Error & { status: number; payload: unknown }).status = response.status;
    (error as Error & { status: number; payload: unknown }).payload = payload;
    throw error;
  }

  return payload;
}

export async function requireUser(req: Request): Promise<{ user: User; admin: SupabaseClient }> {
  const authHeader = req.headers.get('Authorization');
  if (!authHeader?.startsWith('Bearer ')) {
    throw json({ error: 'Missing Authorization bearer token' }, 401);
  }

  const url = Deno.env.get('SUPABASE_URL');
  const anonKey =
    Deno.env.get('SUPABASE_ANON_KEY') ?? Deno.env.get('SUPABASE_PUBLISHABLE_KEY');
  const serviceKey =
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? Deno.env.get('SUPABASE_SECRET_KEY');

  if (!url || !anonKey || !serviceKey) {
    throw json({ error: 'Supabase environment is not configured' }, 500);
  }

  const token = authHeader.slice('Bearer '.length);
  const authClient = createClient(url, anonKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data, error } = await authClient.auth.getUser(token);
  if (error || !data.user) {
    throw json({ error: 'Invalid or expired session' }, 401);
  }

  const admin = createClient(url, serviceKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  return { user: data.user, admin };
}

// Growth-curve params are generated lazily, once per species: if a row
// doesn't have them yet, ask the LLM and persist the result. Best-effort —
// generateGrowthParams() never throws, so a failed/unavailable call just
// returns the row as-is and callers continue unaffected.
export async function ensureGrowthParams(
  admin: SupabaseClient,
  row: PlantBasicInfoRow
): Promise<PlantBasicInfoRow> {
  if (row.growth_mode && row.params_generated_at) {
    return row;
  }

  const generated = await generateGrowthParams(row.scientific_name, row.common_names?.[0] ?? null);
  if (!generated) {
    return row;
  }

  const { data: updated, error: updateError } = await admin
    .from('plant_basic_info')
    .update({ ...generated, params_generated_at: new Date().toISOString() })
    .eq('plant_id', row.plant_id)
    .select()
    .single();

  if (updateError) {
    console.error(`Failed to save growth params for ${row.plant_id}: ${updateError.message}`);
    return row;
  }

  return updated as PlantBasicInfoRow;
}

export async function cachePlantInfo(
  admin: SupabaseClient,
  info: Omit<PlantBasicInfoRow, 'updated_at'>
) {
  const { data: basicInfo, error: infoError } = await admin
    .from('plant_basic_info')
    .upsert(
      { ...info, updated_at: new Date().toISOString() },
      { onConflict: 'plant_id' }
    )
    .select()
    .single();

  if (infoError) {
    throw json({ error: `Failed to save plant_basic_info: ${infoError.message}` }, 500);
  }

  return ensureGrowthParams(admin, basicInfo as PlantBasicInfoRow);
}

export async function saveUserPlant(
  admin: SupabaseClient,
  userId: string,
  info: Omit<PlantBasicInfoRow, 'updated_at'>
) {
  const basicInfo = await cachePlantInfo(admin, info);

  const { data: plant, error: plantError } = await admin
    .from('plants')
    .insert({ user_id: userId, plant_id: info.plant_id })
    .select()
    .single();

  if (plantError) {
    throw json({ error: `Failed to save plant: ${plantError.message}` }, 500);
  }

  return { plant, info: basicInfo };
}

export const PLANT_PHOTOS_BUCKET = 'plant-photos';

function decodeBase64(payload: string): Uint8Array {
  const binary = atob(payload);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

export async function decodePlantImage(image: string): Promise<{
  bytes: Uint8Array;
  contentType: string;
}> {
  const dataUrl = image.match(/^data:([^;]+);base64,(.+)$/s);
  if (dataUrl) {
    return {
      bytes: decodeBase64(dataUrl[2]),
      contentType: dataUrl[1] || 'image/jpeg',
    };
  }

  if (/^https?:\/\//i.test(image)) {
    const response = await fetch(image);
    if (!response.ok) {
      throw json({ error: 'Could not download the plant photo' }, 400);
    }

    return {
      bytes: new Uint8Array(await response.arrayBuffer()),
      contentType: response.headers.get('content-type')?.split(';')[0] || 'image/jpeg',
    };
  }

  try {
    return {
      bytes: decodeBase64(image.replace(/\s/g, '')),
      contentType: 'image/jpeg',
    };
  } catch {
    throw json({ error: 'Could not decode the plant photo' }, 400);
  }
}

export async function uploadPlantPhoto(
  admin: SupabaseClient,
  plantInstanceId: string,
  image: string
) {
  const { bytes, contentType } = await decodePlantImage(image);
  const { error } = await admin.storage.from(PLANT_PHOTOS_BUCKET).upload(plantInstanceId, bytes, {
    contentType,
    upsert: true,
  });

  if (error) {
    throw json({ error: `Failed to store plant photo: ${error.message}` }, 500);
  }

  return { bucket: PLANT_PHOTOS_BUCKET, path: plantInstanceId };
}

export async function saveUserPlantWithPhoto(
  admin: SupabaseClient,
  userId: string,
  info: Omit<PlantBasicInfoRow, 'updated_at'>,
  image: string
) {
  const result = await saveUserPlant(admin, userId, info);

  try {
    const photo = await uploadPlantPhoto(admin, result.plant.id, image);
    const { data: plant, error } = await admin
      .from('plants')
      .update({ photo_path: photo.path })
      .eq('id', result.plant.id)
      .select()
      .single();

    if (error) {
      throw json({ error: `Failed to link plant photo: ${error.message}` }, 500);
    }

    return { plant, info: result.info, photo };
  } catch (error) {
    await admin.from('plants').delete().eq('id', result.plant.id);
    throw error;
  }
}

import { lowercaseKeys } from './json-utils.ts';

// Flower ratio and pollen-per-flower are constants, not a growth curve.
// A photo asks Gemini to correct the previous constants. The hourly accrual
// job multiplies flower_ratio by current leaf area; it does not call the LLM.

export type FlowerPollenConstants = {
  /** Flowers per cm² of leaf area. 0 means the plant is not flowering. */
  flower_ratio: number;
  /** Cubic centimeters of pollen one flower produces over 8 hours. */
  pollen_per_flower_cm3: number;
};

const GEMINI_API_BASE = 'https://generativelanguage.googleapis.com/v1beta/models';
const DEFAULT_GEMINI_MODEL = 'gemini-3.1-flash-lite';

const POLLEN_INTERVAL_HOURS = 8;

export function flowerCountFromLeafArea(leafAreaCm2: number, flowerRatio: number) {
  if (!Number.isFinite(leafAreaCm2) || leafAreaCm2 <= 0 || !Number.isFinite(flowerRatio) || flowerRatio <= 0) {
    return 0;
  }
  return leafAreaCm2 * flowerRatio;
}

export function pollenVolumeCm3(flowerCount: number, pollenPerFlowerCm3: number) {
  if (!Number.isFinite(flowerCount) || flowerCount <= 0 || !Number.isFinite(pollenPerFlowerCm3) || pollenPerFlowerCm3 <= 0) {
    return 0;
  }
  return flowerCount * pollenPerFlowerCm3;
}

export function pollenIntervalElapsed(lastCreditedAt: string | null, now: Date) {
  if (!lastCreditedAt) {
    return false;
  }
  const at = new Date(lastCreditedAt).getTime();
  if (!Number.isFinite(at)) {
    return false;
  }
  return now.getTime() - at >= POLLEN_INTERVAL_HOURS * 60 * 60 * 1000;
}

function buildPrompt(
  scientificName: string | null,
  commonName: string | null,
  previous: FlowerPollenConstants | null
): string {
  const species = scientificName?.trim() || 'Unknown';
  const common = commonName?.trim() || 'Unknown';
  const previousText = previous
    ? `Previous constants for this plant: flower_ratio=${previous.flower_ratio}, pollen_per_flower_cm3=${previous.pollen_per_flower_cm3}. CORRECT them from this photo. These are constants, not a curve. If the plant looks about the same, keep both numbers close to the previous values. Change them only when the photo clearly shows more flowers, fewer flowers, or a different pollen yield.`
    : 'This plant has no previous constants. Estimate them from the species and what you can see in the photo.';

  return `You are looking at a photo of a plant (species: ${species}, common name: ${common}).

Estimate two constants for pollen the plant produces. Do not estimate leaf area or a growth curve.

- flower_ratio: number of flowers per cm² of leaf area. 0 if the plant has no flowers. A typical garden plant in bloom is about 0.001 to 0.05.
- pollen_per_flower_cm3: cubic centimeters of pollen one open flower produces over ${POLLEN_INTERVAL_HOURS} hours. 0 if there are no flowers. Typical values are about 0.01 to 2.

${previousText}

Return only valid JSON: {"flower_ratio": number, "pollen_per_flower_cm3": number}`;
}

function asFiniteNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return value;
  }
  if (typeof value === 'string' && value.trim() !== '') {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

export function validateFlowerPollenConstants(raw: unknown): FlowerPollenConstants | null {
  if (!raw || typeof raw !== 'object') {
    return null;
  }
  const record = raw as Record<string, unknown>;
  const flowerRatio = asFiniteNumber(record.flower_ratio);
  const pollenPerFlower = asFiniteNumber(record.pollen_per_flower_cm3);
  if (flowerRatio == null || flowerRatio < 0 || flowerRatio > 1) {
    return null;
  }
  if (pollenPerFlower == null || pollenPerFlower < 0 || pollenPerFlower > 20) {
    return null;
  }
  if (flowerRatio === 0) {
    return { flower_ratio: 0, pollen_per_flower_cm3: 0 };
  }
  return { flower_ratio: flowerRatio, pollen_per_flower_cm3: pollenPerFlower };
}

export async function generateFlowerPollenParams(
  imageBase64: string,
  mimeType: string,
  scientificName: string | null,
  commonName: string | null,
  previous: FlowerPollenConstants | null
): Promise<FlowerPollenConstants | null> {
  try {
    const apiKey = Deno.env.get('GEMINI_KEY');
    if (!apiKey) {
      console.error('GEMINI_KEY is not set; skipping flower and pollen constants');
      return null;
    }

    const model = Deno.env.get('GEMINI_MODEL')?.trim() || DEFAULT_GEMINI_MODEL;
    const url = `${GEMINI_API_BASE}/${model}:generateContent?key=${encodeURIComponent(apiKey)}`;
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [
          {
            parts: [
              { inline_data: { mime_type: mimeType, data: imageBase64 } },
              { text: buildPrompt(scientificName, commonName, previous) },
            ],
          },
        ],
        generationConfig: { responseMimeType: 'application/json' },
      }),
    });

    if (!response.ok) {
      console.error(`Flower pollen Gemini request failed (${response.status})`);
      return null;
    }

    const payload = await response.json().catch(() => null);
    const text = payload?.candidates?.[0]?.content?.parts?.[0]?.text;
    if (typeof text !== 'string' || text.trim().length === 0) {
      return null;
    }

    const parsed = JSON.parse(text);
    const normalized = typeof parsed === 'object' && parsed !== null ? lowercaseKeys(parsed) : parsed;
    const validated = validateFlowerPollenConstants(normalized);
    if (!validated) {
      console.error('FLOWER_POLLEN_DEBUG: validation rejected', text);
    }
    return validated;
  } catch (error) {
    console.error('generateFlowerPollenParams failed:', error);
    return null;
  }
}

export function lowercaseKeys(obj: Record<string, unknown>): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const key of Object.keys(obj)) {
    result[key.toLowerCase()] = obj[key];
  }
  return result;
}

// Growth-curve model for estimating a plant's leaf area over time.
//
// y(x) = L · G(x) · P(x) · M(x)
//
//   G(x) — germination/emergence gate (logistic, ramps 0 -> 1 around xg)
//   P(x) — main logistic growth term (ramps 0 -> 1 around x0)
//   M(x) — growth-mode-specific modifier (see GrowthMode below)
//
// Column names below intentionally mirror public.plant_basic_info
// (see supabase/migrations/20260913054225_add_growth_curve_params.sql)
// so a row from that table can be passed in directly.

export type GrowthMode = 'annual_bounded' | 'woody_residual' | 'cyclical';

export type GrowthCurveParams = {
  growth_mode: GrowthMode;
  /** Peak/mature leaf area (cm²) — carrying capacity. */
  l: number;
  /** Growth rate constant for the main logistic term P(x). */
  k: number;
  /** Day of maximum growth rate (inflection point) in P(x). */
  x0: number;
  /** Germination/emergence midpoint day, used in G(x). */
  xg: number;
  /** Germination steepness constant, used in G(x). */
  kg: number;

  // annual_bounded only
  /** Steepness constant for the senescence term (distinct from k). */
  ks?: number | null;
  /** Senescence onset day. */
  xs?: number | null;
  /** Long-term canopy retention floor, as a fraction of L. */
  f?: number | null;

  // woody_residual only
  /** Residual growth rate (cm²/day) added after xs. */
  r?: number | null;
  // woody_residual reuses `xs` above as the residual-growth start day.

  // cyclical only
  /** Days per growth cycle (e.g. ~365 for annual die-back perennials). */
  cycle_length?: number | null;
  /** Persistent crown/root leaf-area baseline (cm²) that survives dormancy. */
  b_base?: number | null;
  /** New seasonal leaf area regrown each cycle (cm²). */
  l_season?: number | null;
};

function requireParam(value: number | null | undefined, name: string, growthMode: GrowthMode): number {
  if (value == null || !Number.isFinite(value)) {
    throw new Error(`growth_mode '${growthMode}' requires numeric param '${name}'`);
  }
  return value;
}

function logistic(steepness: number, x: number, midpoint: number): number {
  return 1 / (1 + Math.exp(-steepness * (x - midpoint)));
}

/** Modulo that always returns a value in [0, modulus), unlike JS `%`. */
function positiveMod(value: number, modulus: number): number {
  return ((value % modulus) + modulus) % modulus;
}

function evaluateM(params: GrowthCurveParams, x: number): number {
  switch (params.growth_mode) {
    case 'annual_bounded': {
      const ks = requireParam(params.ks, 'ks', params.growth_mode);
      const xs = requireParam(params.xs, 'xs', params.growth_mode);
      const f = requireParam(params.f, 'f', params.growth_mode);
      return 1 - (1 - f) / (1 + Math.exp(-ks * (x - xs)));
    }

    case 'woody_residual': {
      const r = requireParam(params.r, 'r', params.growth_mode);
      const xs = requireParam(params.xs, 'xs', params.growth_mode);
      return 1 + (r * Math.max(0, x - xs)) / params.l;
    }

    case 'cyclical': {
      const cycleLength = requireParam(params.cycle_length, 'cycle_length', params.growth_mode);
      const bBase = requireParam(params.b_base, 'b_base', params.growth_mode);
      const lSeason = requireParam(params.l_season, 'l_season', params.growth_mode);
      const xSeason = positiveMod(x, cycleLength);
      return bBase / params.l + (lSeason / params.l) * logistic(params.k, xSeason, params.x0);
    }

    default: {
      const exhaustive: never = params.growth_mode;
      throw new Error(`Unknown growth_mode: ${String(exhaustive)}`);
    }
  }
}

export function evaluateGrowthCurve(params: GrowthCurveParams, x: number): number {
  const g = logistic(params.kg, x, params.xg);
  const p = logistic(params.k, x, params.x0);
  const m = evaluateM(params, x);
  return params.l * g * p * m;
}

export type SolveXForFullnessOptions = {
  /** Lower bound of the search range, in days. Defaults to 0. */
  minX?: number;
  /**
   * Upper bound of the search range, in days. Defaults to cycle_length for
   * 'cyclical' plants and 3650 (10 years) otherwise.
   */
  maxX?: number;
  /** Stop bisecting once the bracket width is at most this many days. Defaults to 0.01. */
  toleranceX?: number;
  /** Max bisection iterations, as a backstop against a non-converging search. */
  maxIterations?: number;
};

const SOLVE_SCAN_STEP_DAYS = 0.5;

/**
 * Finds x such that evaluateGrowthCurve(params, x) / params.l ≈ fullnessPct / 100.
 *
 * Works for curves that rise and fall (annual_bounded after senescence,
 * cyclical): it scans forward from minX in 0.5-day steps, finds the first day
 * whose fullness reaches the target, then bisects between the last day below
 * the target and that day. For 'cyclical' plants only [0, cycle_length] is
 * scanned, i.e. the first cycle. If no scanned day reaches the target, it
 * returns the scanned day whose fullness is closest to the target.
 *
 * Never throws and never returns null: on any error (e.g. missing params) it
 * returns minX.
 */
export function solveXForFullness(
  params: GrowthCurveParams,
  fullnessPct: number,
  options?: SolveXForFullnessOptions
): number {
  const minX = options?.minX ?? 0;

  try {
    const toleranceX = options?.toleranceX ?? 0.01;
    const maxIterations = options?.maxIterations ?? 200;
    const cycleLength = params.growth_mode === 'cyclical' ? params.cycle_length : null;
    const defaultMaxX = cycleLength != null && Number.isFinite(cycleLength) && cycleLength > 0 ? cycleLength : 3650;
    const maxX = options?.maxX ?? defaultMaxX;

    const target = fullnessPct / 100;
    const fullnessAt = (x: number) => {
      const value = evaluateGrowthCurve(params, x) / params.l;
      return Number.isFinite(value) ? value : 0;
    };

    let prevX = minX;
    const startValue = fullnessAt(minX);
    if (startValue >= target) {
      return minX;
    }

    let bestX = minX;
    let bestDiff = Math.abs(startValue - target);

    for (let step = 1; minX + step * SOLVE_SCAN_STEP_DAYS <= maxX + 1e-9; step += 1) {
      const x = minX + step * SOLVE_SCAN_STEP_DAYS;
      const value = fullnessAt(x);
      const diff = Math.abs(value - target);
      if (diff < bestDiff) {
        bestDiff = diff;
        bestX = x;
      }

      if (value >= target) {
        let lo = prevX;
        let hi = x;
        for (let i = 0; i < maxIterations && hi - lo > toleranceX; i += 1) {
          const mid = (lo + hi) / 2;
          if (fullnessAt(mid) < target) {
            lo = mid;
          } else {
            hi = mid;
          }
        }
        return (lo + hi) / 2;
      }

      prevX = x;
    }

    return bestX;
  } catch {
    return minX;
  }
}

// ---------------------------------------------------------------------------
// Inline tests. This project has no test runner configured (no jest/vitest,
// no *.test.* files anywhere), so these follow the Deno convention used by
// the edge functions themselves: run directly with
//   deno run supabase/functions/_shared/growth-curve.ts
// and guarded by `import.meta.main` so importing this module elsewhere never
// executes them.
// ---------------------------------------------------------------------------

if (import.meta.main) {
  const approxEqual = (actual: number, expected: number, tolerance: number) =>
    Math.abs(actual - expected) <= tolerance;

  function check(name: string, actual: number, expected: number, tolerance: number) {
    const pass = approxEqual(actual, expected, tolerance);
    const status = pass ? 'PASS' : 'FAIL';
    console.log(`[${status}] ${name}: got ${actual.toFixed(4)}, expected ~${expected} (±${tolerance})`);
  }

  // The source PDF's reference table gives y(180) ≈ 941.87, but that value is
  // wrong: it's been independently hand-verified (and confirmed against x=45,
  // x=90, and x=120 as well) that the table contains multiple arithmetic
  // errors. Evaluating the equation directly, as implemented here, is the
  // ground truth — this test asserts against that (918.84), not the table.
  const annualBounded: GrowthCurveParams = {
    growth_mode: 'annual_bounded',
    l: 1000,
    k: 0.05,
    x0: 120,
    xg: 45,
    kg: 0.2,
    xs: 200,
    f: 0.9,
    ks: 0.03,
  };
  check('annual_bounded y(180) matches direct equation evaluation', evaluateGrowthCurve(annualBounded, 180), 918.84, 1);

  // Sanity checks that don't depend on the missing ks value:

  // Long before germination/growth, output should be ~0.
  check('annual_bounded y(0) ~ 0', evaluateGrowthCurve(annualBounded, 0), 0, 1);

  // Well past senescence, M(x) -> f, G(x) and P(x) -> 1, so y(x) -> L * f.
  check('annual_bounded y(2000) -> L*f', evaluateGrowthCurve(annualBounded, 2000), 1000 * 0.9, 0.5);

  // woody_residual: past xs, growth adds r*(x-xs) on top of L*G*P.
  const woodyResidual: GrowthCurveParams = {
    growth_mode: 'woody_residual',
    l: 1000,
    k: 0.05,
    x0: 120,
    xg: 45,
    kg: 0.2,
    xs: 200,
    r: 2,
  };
  // At x = xs, the residual term is exactly 0, so M(xs) = 1 and
  // y(xs) = L * G(xs) * P(xs).
  const gAtXs = 1 / (1 + Math.exp(-0.2 * (200 - 45)));
  const pAtXs = 1 / (1 + Math.exp(-0.05 * (200 - 120)));
  check('woody_residual y(xs) == L*G(xs)*P(xs)', evaluateGrowthCurve(woodyResidual, 200), 1000 * gAtXs * pAtXs, 0.01);

  // 300 days past xs, M = 1 + 2*300/1000 = 1.6, and G/P are both ~1 by then.
  check('woody_residual y(500) ~ L*1.6', evaluateGrowthCurve(woodyResidual, 500), 1000 * 1.6, 1);

  // cyclical: P(x) multiplies the seasonal term and is evaluated on raw x, so
  // y = L * G(x) * P(x) * M(x). At x = x0 the P term is exactly 0.5 and the
  // season's logistic is also 0.5.
  const cyclical: GrowthCurveParams = {
    growth_mode: 'cyclical',
    l: 500,
    k: 0.1,
    x0: 60,
    xg: 10,
    kg: 0.3,
    cycle_length: 365,
    b_base: 50,
    l_season: 450,
  };
  const gAt60 = 1 / (1 + Math.exp(-0.3 * (60 - 10)));
  const pAt60 = 0.5;
  check(
    'cyclical y(60) = L*G*P*M at season inflection',
    evaluateGrowthCurve(cyclical, 60),
    500 * gAt60 * pAt60 * (50 / 500 + 450 / 500 / 2),
    0.01
  );
  // One full cycle later the seasonal term wraps back to the same point, but
  // P(x) is on raw x (not periodic): P(425) = 1/(1+e^(-0.1*365)) ~ 1, not 0.5.
  const pAt425 = 1 / (1 + Math.exp(-0.1 * (60 + 365 - 60)));
  const gAt425 = 1 / (1 + Math.exp(-0.3 * (60 + 365 - 10)));
  check(
    'cyclical y(60 + cycle_length) uses raw-x P(x), so differs from y(60)',
    evaluateGrowthCurve(cyclical, 60 + 365),
    500 * gAt425 * pAt425 * (50 / 500 + 450 / 500 / 2),
    0.001
  );
  // Once P(x) has saturated, later cycles do repeat exactly.
  check(
    'cyclical y(x + cycle_length) matches y(x) once P(x) ~ 1',
    evaluateGrowthCurve(cyclical, 200 + 365),
    evaluateGrowthCurve(cyclical, 200),
    1
  );

  // solveXForFullness: round-trip against evaluateGrowthCurve for a mode
  // that's monotonic over the whole search range.
  const targetX = 300;
  const fullnessAtTargetX = (evaluateGrowthCurve(woodyResidual, targetX) / woodyResidual.l) * 100;
  const solvedX = solveXForFullness(woodyResidual, fullnessAtTargetX);
  check('solveXForFullness round-trips woody_residual', solvedX, targetX, 1);

  const fullnessPctAt = (params: GrowthCurveParams, x: number) => (evaluateGrowthCurve(params, x) / params.l) * 100;
  const checkInRange = (name: string, actual: number, min: number, max: number) => {
    const pass = actual >= min && actual <= max;
    console.log(`[${pass ? 'PASS' : 'FAIL'}] ${name}: got ${actual.toFixed(4)}, expected in [${min}, ${max}]`);
  };

  // woody_residual: a target at or below the day-0 fullness returns minX.
  check('solveXForFullness woody 0% returns minX', solveXForFullness(woodyResidual, 0), 0, 0);

  // annual_bounded: rises, then declines toward f after senescence. A target on
  // the rising side round-trips.
  const annualTargetX = 90;
  check(
    'solveXForFullness round-trips annual_bounded (rising side)',
    solveXForFullness(annualBounded, fullnessPctAt(annualBounded, annualTargetX)),
    annualTargetX,
    0.5
  );
  // annual_bounded: a target above the curve's peak is unreachable, so the
  // solver returns the closest day (the peak) instead of failing.
  const annualValues = Array.from({ length: 3651 }, (_, i) => evaluateGrowthCurve(annualBounded, i) / annualBounded.l);
  const annualPeakDay = annualValues.indexOf(Math.max(...annualValues));
  const annualClosestX = solveXForFullness(annualBounded, 100);
  checkInRange('solveXForFullness annual_bounded unreachable returns the peak day', annualClosestX, annualPeakDay - 1, annualPeakDay + 1);

  // cyclical: l=450, k=0.15, x0=20, 50% target. The curve reaches 50% around
  // day 25; day 3650 sits at the start of a cycle (~15%), which used to make
  // the solver return 3650.
  const cyclicalRegression: GrowthCurveParams = {
    growth_mode: 'cyclical',
    l: 450,
    k: 0.15,
    x0: 20,
    xg: 0,
    kg: 0.2,
    cycle_length: 365,
    b_base: 50,
    l_season: 400,
  };
  const cyclicalSolved = solveXForFullness(cyclicalRegression, 50);
  checkInRange('solveXForFullness cyclical 50% target is ~day 15-30', cyclicalSolved, 15, 30);
  check('solveXForFullness cyclical result evaluates to 50%', fullnessPctAt(cyclicalRegression, cyclicalSolved), 50, 0.5);

  // Never fails: odd targets on every mode return finite numbers.
  for (const [label, params] of [
    ['annual_bounded', annualBounded],
    ['woody_residual', woodyResidual],
    ['cyclical', cyclicalRegression],
  ] as const) {
    for (const pct of [-10, 0, 100, 250]) {
      const x = solveXForFullness(params, pct);
      console.log(`[${Number.isFinite(x) ? 'PASS' : 'FAIL'}] solveXForFullness ${label} ${pct}% is finite: ${x}`);
    }
  }

  // Missing required params must not throw; falls back to minX.
  const brokenCyclical = { ...cyclicalRegression, b_base: null } as GrowthCurveParams;
  check('solveXForFullness with missing params returns minX', solveXForFullness(brokenCyclical, 50), 0, 0);
}

import type { GrowthCurveParams, GrowthMode } from './growth-curve.ts';
import { lowercaseKeys } from './json-utils.ts';

// Generates growth-curve parameters (see growth-curve.ts) for a species by
// asking Gemini, then validates/clamps the response against known-sane
// bounds. Best-effort only: every failure path (missing key, network error,
// bad JSON, a field out of range) returns null rather than throwing, so a
// misbehaving LLM call can never break the plant-saving flow that calls it.

export type GeneratedGrowthParams = GrowthCurveParams & {
  carbon_fraction: number;
  confidence: number;
};

const GEMINI_API_BASE = 'https://generativelanguage.googleapis.com/v1beta/models';
// Not specified by the request — defaulting to a current, fast Gemini model.
// Override with the GEMINI_MODEL secret if a different one is wanted.
const DEFAULT_GEMINI_MODEL = 'gemini-3.1-flash-lite';

const VALID_GROWTH_MODES: GrowthMode[] = ['annual_bounded', 'woody_residual', 'cyclical'];

function buildPrompt(scientificName: string | null, commonName: string | null): string {
  const species = scientificName?.trim() || 'Unknown';
  const common = commonName?.trim() || 'Unknown';

  return `Species: ${species}
Common name: ${common}

Classify this species into exactly one growth_mode:
- "annual_bounded": annuals, determinate vegetables, most houseplants that reach a stable mature size and hold there
- "woody_residual": trees, shrubs, woody perennials that keep slowly growing indefinitely after initial maturity
- "cyclical": herbaceous perennials that die back and regrow each season (mint, chives, perennial flowers)

Then estimate these parameters for typical garden/houseplant growing conditions:

Always required:
- L: mature/peak leaf area in cm²
- x0: day of maximum growth rate
- k: growth rate constant (typically 0.02-0.3)
- xg: typical germination/emergence day from seed
- kg: germination steepness constant (typically 0.1-0.3)
- carbon_fraction: fraction of dry biomass that is carbon (typically 0.40-0.55)

Required if growth_mode is "annual_bounded":
- xs: day canopy stabilization begins
- ks: senescence steepness constant
- f: long-term retention floor as fraction of L (typically 0.7-0.95)

Required if growth_mode is "woody_residual":
- xs: day residual growth phase begins
- r: residual growth rate in cm²/day after xs

Required if growth_mode is "cyclical":
- cycle_length: days per growth cycle (typically 365)
- b_base: persistent crown/root leaf-equivalent baseline in cm²
- l_season: new seasonal leaf area regrown each cycle in cm²

Also return confidence: a number 0-1 reflecting how well-documented this species' growth pattern is.

Return only valid JSON with only the fields relevant to your chosen growth_mode populated.`;
}

async function callGemini(apiKey: string, prompt: string): Promise<unknown | null> {
  const model = Deno.env.get('GEMINI_MODEL')?.trim() || DEFAULT_GEMINI_MODEL;
  const url = `${GEMINI_API_BASE}/${model}:generateContent?key=${encodeURIComponent(apiKey)}`;

  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: {
        responseMimeType: 'application/json',
      },
    }),
  });

  if (!response.ok) {
    console.error(`Gemini request failed (${response.status}): ${await response.text().catch(() => '')}`);
    return null;
  }

  const payload = await response.json().catch(() => null);
  const text = payload?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (typeof text !== 'string' || text.trim().length === 0) {
    console.error('Gemini response did not contain text content');
    return null;
  }

  try {
    const parsed = JSON.parse(text);
    return typeof parsed === 'object' && parsed !== null ? lowercaseKeys(parsed) : parsed;
  } catch (error) {
    console.error('Gemini response was not valid JSON:', error, text);
    return null;
  }
}

// ---------------------------------------------------------------------------
// Validation
//
// Two kinds of fields:
//  - hard/required: missing, non-finite, or outside [min, max] => whole
//    result is rejected (returns null).
//  - soft: clamped into [min, max], with a sane default when missing.
// ---------------------------------------------------------------------------

function asFiniteNumber(value: unknown): number | null {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return value;
  }
  if (typeof value === 'string' && value.trim() !== '') {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

/** Hard field: null (reject) if missing, non-finite, or outside [min, max]. */
function requireInRange(value: unknown, min: number, max: number): number | null {
  const num = asFiniteNumber(value);
  if (num == null || num < min || num > max) {
    return null;
  }
  return num;
}

/** Soft field: clamps into [min, max], falling back to defaultValue when missing/invalid. */
function clampOrDefault(value: unknown, min: number, max: number, defaultValue: number): number {
  const num = asFiniteNumber(value);
  if (num == null) {
    return defaultValue;
  }
  return Math.min(max, Math.max(min, num));
}

export function validateGrowthParams(raw: unknown): GeneratedGrowthParams | null {
  if (!raw || typeof raw !== 'object') {
    return null;
  }
  const record = raw as Record<string, unknown>;

  const growthMode = typeof record.growth_mode === 'string' ? record.growth_mode : null;
  if (!growthMode || !VALID_GROWTH_MODES.includes(growthMode as GrowthMode)) {
    return null;
  }

  const l = requireInRange(record.l, 1, 5000000);
  const k = requireInRange(record.k, 0.001, 1.0);
  const x0 = requireInRange(record.x0, 1, 3650);
  const xg = requireInRange(record.xg, 0, 365);
  const kg = requireInRange(record.kg, 0.001, 1.0);
  if (l == null || k == null || x0 == null || xg == null || kg == null) {
    return null;
  }

  const carbonFraction = clampOrDefault(record.carbon_fraction, 0.35, 0.55, 0.45);
  const confidence = clampOrDefault(record.confidence, 0, 1, 0.5);

  const base = { growth_mode: growthMode as GrowthMode, l, k, x0, xg, kg, carbon_fraction: carbonFraction, confidence };

  switch (base.growth_mode) {
    case 'annual_bounded': {
      const xs = requireInRange(record.xs, 1, 3650);
      const ks = requireInRange(record.ks, 0.001, 1.0);
      if (xs == null || ks == null) {
        return null;
      }
      const f = clampOrDefault(record.f, 0.5, 0.99, 0.85);
      return { ...base, xs, ks, f };
    }

    case 'woody_residual': {
      const xs = requireInRange(record.xs, 1, 3650);
      const r = requireInRange(record.r, 0.001, 1000);
      if (xs == null || r == null) {
        return null;
      }
      return { ...base, xs, r };
    }

    case 'cyclical': {
      const cycleLength = requireInRange(record.cycle_length, 30, 730);
      const bBase = requireInRange(record.b_base, 0, 100000);
      const lSeason = requireInRange(record.l_season, 1, 100000);
      if (cycleLength == null || bBase == null || lSeason == null) {
        return null;
      }
      return { ...base, cycle_length: cycleLength, b_base: bBase, l_season: lSeason };
    }
  }
}

export async function generateGrowthParams(
  scientificName: string | null,
  commonName: string | null
): Promise<GeneratedGrowthParams | null> {
  try {
    const apiKey = Deno.env.get('GEMINI_KEY');
    if (!apiKey) {
      console.error('GEMINI_KEY is not set; skipping growth-param generation');
      return null;
    }

    console.log('GROWTH_PARAMS_DEBUG: called for', scientificName, commonName);
    const prompt = buildPrompt(scientificName, commonName);
    const raw = await callGemini(apiKey, prompt);
    if (raw == null) {
      return null;
    }

    console.log('GROWTH_PARAMS_DEBUG: raw Gemini response:', JSON.stringify(raw));

    const validated = validateGrowthParams(raw);
    if (validated == null) {
      console.error('GROWTH_PARAMS_DEBUG: validation rejected the response above');
    }
    return validated;
    } catch (error) {
